SELECT cs.canonical_smiles, substr_cr.compound_name AS substrate_compound_name, parent_cr.compound_name AS parent_compound_name, m.met_conversion, m.pathway_key, m.organism, m.enzyme_name FROM metabolism m JOIN compound_records substr_cr ON m.substrate_record_id = substr_cr.record_id JOIN compound_structures cs ON substr_cr.molregno = cs.molregno JOIN compound_records parent_cr ON m.drug_record_id = parent_cr.record_id WHERE m.enzyme_name = 'CYP2A6' ORDER BY cs.canonical_smiles ASC, substr_cr.compound_name ASC, parent_cr.compound_name ASC, m.met_conversion ASC, m.pathway_key ASC, m.organism ASC, m.enzyme_name ASC LIMIT 200
